// C implementation of vstodo cmdRebase header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_rebase.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_rebase.go.\n\n#ifndef VSTODO_C_CMD_REBASE_H\n#define VSTODO_C_CMD_REBASE_H\n\n// Rewrite commit history by rebasing the current branch.\n// Equivalent to Go cmdRebase function.\n// app — vstodo application context pointer\n// args — rebase options and target branch\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_rebase(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_REBASE_H